LINE = re.compile(r'^ "(?:[^"\\]|\\.)*", \[.*\],$', re.M)
by = {}
for qid, v in P.items():
    seg, n = qid.split("-"); by.setdefault(seg, {})[int(n)] = v
for seg, fixes in by.items():
    path = os.path.join(HERE, "src", MOD[seg] + ".py"); s = open(path).read()
    ms = list(LINE.finditer(s)); out = []; last = 0
    for i, m in enumerate(ms, 1):
        out.append(s[last:m.start()])
        if i in fixes:
            k, w = fixes[i]; out.append(" " + json.dumps(k, ensure_ascii=False) + ", " + json.dumps(w, ensure_ascii=False) + ",")
        else:
            out.append(m.group(0))
        last = m.end()
    out.append(s[last:]); open(path, "w").write("".join(out))
    print(seg, len(ms), "items,", len(fixes), "patched")
